def _fstype(path):
    """Return the type of the mounted filesystem containing path on Linux."""
    target = os.path.realpath(path)
    best = ('', '')
    try:
        with open('/proc/self/mountinfo', encoding='utf-8') as mounts:
            for line in mounts:
                fields = line.rstrip('\n').split(' ')
                sep = fields.index('-')
                mount = fields[4].replace('\\040', ' ').replace('\\011', '\t').replace('\\134', '\\')
                if (target == mount or target.startswith(mount.rstrip('/') + '/')) and len(mount) > len(best[0]):
                    best = (mount, fields[sep + 1])
    except (OSError, ValueError, IndexError):
        pass
    return best[1]


